// InputFieldGroup.stories.tsx
import type { Meta, StoryObj } from "@storybook/react-webpack5";

import { useState } from "react";

import { InputFieldGroup, Typography } from "~baseComponents";

import { CardWrapperItem } from "../CardWrapperItem";

const meta = {
  title: "BaseComponents/InputFieldGroup",
  component: InputFieldGroup,
  parameters: { layout: "centered" },
  tags: ["autodocs"],
  argTypes: {
    length: { control: "number" },
    code: { control: "object" },
    isFocused: { control: "boolean" },
    "aria-label": { control: "text" },
    setIsFocused: { control: "object" },
    handleInputChange: { control: "object" },
    hintText: { control: "text" },
    isError: { control: "boolean" },
  },
  args: {
    length: 6,
    code: [],
    isFocused: false,
    "aria-label": "Поле для кода",
    setIsFocused: () => {},
    handleInputChange: () => () => {},
  },
} satisfies Meta<typeof InputFieldGroup>;

export default meta;
type Story = StoryObj<typeof meta>;

const InteractiveInputFieldGroup = () => {
  const length = 6;
  const [code, setCode] = useState<string[]>(Array.from({ length }, () => ""));
  const [isFocused, setIsFocused] = useState<boolean>(false);

  const handleInputChange =
    (index: number) => (e: React.ChangeEvent<HTMLInputElement>) => {
      setCode((prev) => {
        const copy = [...prev];
        copy[index] = e.target.value;
        return copy;
      });
    };

  return (
    <CardWrapperItem>
      <div
        style={{
          background: "#fff",
          borderRadius: "12px",
          padding: "16px",
        }}
      >
        <Typography
          tag="span"
          fontClass="heading3"
          style={{
            display: "flex",
            justifyContent: "center",
            marginBottom: "12px",
          }}
        >
          Code: {code}
        </Typography>

        <div
          style={{ display: "flex", gap: "8px" }}
          data-testid="InputField_GROUP"
        >
          <InputFieldGroup
            length={length}
            code={code}
            isFocused={isFocused}
            aria-label="Поле для кода"
            setIsFocused={setIsFocused}
            handleInputChange={handleInputChange}
          />
        </div>
      </div>
    </CardWrapperItem>
  );
};

export const Default: Story = {
  args: {
    length: 6,
    code: [],
    isFocused: false,
    "aria-label": "Поле для кода",
    setIsFocused: () => {},
    handleInputChange: () => () => {},
  },
};

export const Interactive: Story = {
  render: () => {
    return <InteractiveInputFieldGroup />;
  },
};

export const WithHintText: Story = {
  args: {
    length: 6,
    code: [],
    isFocused: false,
    "aria-label": "Поле для кода",
    setIsFocused: () => {},
    handleInputChange: () => () => {},
    hintText: "Hint Text",
  },
};

export const WithError: Story = {
  args: {
    length: 6,
    code: [],
    isFocused: false,
    "aria-label": "Поле для кода",
    setIsFocused: () => {},
    handleInputChange: () => () => {},
    isError: true,
    hintText:
      "Код не верный, попробуйте еще раз! При вводе неправильного SMS-кода регистрация будет заблокирована, количество попыток 3.",
  },
};
